def algorithm(func, dim, lb, ub, budget, rng):
    def objective(x):
        return func(x)

    best_x = np.random.uniform(lb, ub, size=dim)
    best_y = objective(best_x)

    for i in range(budget):
        if i < 10:
            # Initial phase: Random Search
            x = np.random.uniform(lb, ub, size=dim)
            y = objective(x)
            if y < best_y:
                best_x = x
                best_y = y

        else:
            # Adaptation phase: CMA-ES
            mean = best_x
            cov = rng.rand(dim) * 0.5 + 0.25
            cov = np.outer(cov, cov)
            step_size = 1 / np.sqrt(np.diag(cov))

            new_mean = mean + np.random.multivariate_normal(mean, cov * step_size**2)
            new_mean = np.clip(new_mean, lb, ub)

            y_new = objective(new_mean)
            if y_new < best_y:
                best_x = new_mean
                best_y = y_new

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    def Rosenbrock(x):
        return func(np.array([1] * 5)) if np.allclose(x, [1] * 5) else func(x)

    def clip_bounds(x, lb, ub):
        return np.clip(x, a_min=lb, a_max=ub)

    def generate_initial_population(pop_size, dim, lb, ub):
        return rng.uniform(lb, ub, size=(pop_size, dim))

    def sim_annealing(func, x0, T, alpha, budget, lb, ub):
        x_best = x0
        f_best = func(x0)
        for _ in range(budget):
            delta = 1e-3 * rng.randn(dim)
            new_x = clip_bounds(x_best + delta, lb, ub)
            new_f = func(new_x)
            if new_f < f_best:
                x_best = new_x
                f_best = new_f
            else:
                probability = np.exp((f_best - new_f) / T)
                if rng.rand() < probability:
                    x_best = new_x
                    f_best = new_f
            T *= alpha
        return x_best

    def differential_evolution(func, pop_size, dim, lb, ub, budget):
        population = generate_initial_population(pop_size, dim, lb, ub)
        for _ in range(budget):
            differences = np.array([population[i] - population[(i+1) % pop_size] for i in range(pop_size)])
            indices = rng.choice(pop_size, size=pop_size, replace=False)
            new_population = population.copy()
            for i in range(pop_size):
